INSERT OR IGNORE INTO restaurants
(slug, destination_id, name, cuisine, summary, description, image, lat, lng, address, price_for_two, rating, reviews_count, opening_hours, opens_at, closes_at, menu_summary) VALUES
('mango-tree-hampi',1,'Mango Tree','South Indian, Continental','A shaded garden restaurant above the river.','Long tables under mango trees, with a menu that runs from filter coffee and dosa to wood-fired pizza. The sunset view over the boulders is the reason to stay for a second pot of tea.','/images/food.jpg',15.3340,76.4610,'River Road, Hampi',700,4.4,1240,'8:00 AM - 10:00 PM','08:00','22:00','Ghee roast dosa · Banana pancake · Wood-fired pizza · Fresh lime soda'),
('hampi-bazaar-kitchen',1,'Bazaar Kitchen','North Indian, Thali','Home-style thalis served in the old bazaar.','A small family kitchen with a changing daily thali, unlimited rice and a courtyard with four tables. Lunch is the main service.','/images/food.jpg',15.3355,76.4605,'Hampi Bazaar',450,4.3,620,'11:00 AM - 9:30 PM','11:00','21:30','Unlimited thali · Dal fry · Chapati · Curd rice'),
('royal-thali-mysore',2,'Royal Thali House','Karnataka, Vegetarian','A Mysore thali institution near the palace.','Served on a banana leaf with twelve small bowls, this is the city''s most reliable vegetarian lunch. The queue moves quickly and the filter coffee is excellent.','/images/food.jpg',12.3070,76.6530,'Sayyaji Rao Road, Mysore',600,4.5,2140,'11:00 AM - 4:00 PM, 7:00 PM - 10:00 PM','11:00','22:00','Banana leaf thali · Mysore masala dosa · Rasam · Filter coffee'),
('silk-and-spice',2,'Silk and Spice','Modern Indian','A rooftop kitchen with a modern take on Mysore food.','Small plates built around local spices, with a short cocktail list and a view over the palace dome. Reserve for the 7 PM seating.','/images/food.jpg',12.3040,76.6560,'Vinoba Road, Mysore',1600,4.4,860,'12:30 PM - 3:00 PM, 7:00 PM - 11:00 PM','12:30','23:00','Pandi curry · Akki roti · Sandalwood smoked paneer · Filter coffee panna cotta'),
('coorg-pandi-kitchen',3,'Pandi Kitchen','Kodava','Slow-cooked Kodava pork and bamboo shoot curry.','A family-run kitchen serving the food of the Kodagu households, with pork, bamboo shoot and kadambuttu rice dumplings. Book a table for dinner, and ask what came from the garden that day.','/images/food.jpg',12.4100,75.7400,'Madikeri, Coorg',1100,4.6,540,'12:00 PM - 3:00 PM, 7:00 PM - 10:00 PM','12:00','22:00','Pandi curry · Kadambuttu · Bamboo shoot palya · Coorg honey'),
('estate-table-coorg',3,'The Estate Table','Continental, Indian','A plantation lunch with produce from the estate.','Set in a coffee estate dining room, the fixed lunch uses vegetables and greens grown on the property. Vegetarian and non-vegetarian menus both available.','/images/food.jpg',12.3700,75.8000,'Pollibetta, Coorg',1400,4.5,320,'12:30 PM - 3:00 PM','12:30','15:00','Estate salad · Coorg chicken curry · Cardamom pudding'),
('chikmagalur-estate-cafe',4,'Kaimara Estate Cafe','Cafe, Indian','Breakfast and filter coffee inside a coffee estate.','A small cafe attached to the estate office, with a short menu of idli, dosa, eggs and estate coffee. Good before a Mullayanagiri drive.','/images/food.jpg',13.3250,75.7750,'Kaimara, Chikmagalur',400,4.4,380,'7:30 AM - 6:00 PM','07:30','18:00','Idli · Masala dosa · Estate filter coffee · Banana bread'),
('gokarna-shack',5,'Kudle Sunset Shack','Seafood, Continental','Fish curry and pancakes on the sand.','A long-running shack at the south end of Kudle Beach, with the day''s catch grilled to order. Breakfast runs until noon, and the sunset seats go early.','/images/food.jpg',14.5170,74.3120,'Kudle Beach, Gokarna',700,4.3,720,'8:00 AM - 10:30 PM','08:00','22:30','Grilled kingfish · Fish curry rice · Nutella pancake · Lime soda'),
('kabini-forest-dining',6,'Forest Dining Room','Indian, Continental','A lodge restaurant with a native-ingredient menu.','The dining room at the safari lodge serves a set menu built around local grains and produce. Packed breakfasts are available for the dawn drive.','/images/food.jpg',11.9180,76.1820,'Karapur, Kabini',1800,4.4,210,'6:30 AM - 10:00 PM','06:30','22:00','Millet upma · Coorg chicken · River fish · Seasonal fruit'),
('munnar-tea-house',7,'The Tea House','Cafe, Indian','Cardamom tea and warm food above the tea slopes.','A glass-walled cafe on a ridge with a short menu of sandwiches, soups and tea. Best in the late afternoon when the mist comes in.','/images/food.jpg',10.0920,77.0620,'Chithirapuram, Munnar',600,4.3,980,'8:00 AM - 8:00 PM','08:00','20:00','Cardamom tea · Masala omelette · Chicken sandwich · Banana cake'),
('munnar-spice-garden',7,'Spice Garden Restaurant','Kerala','Kerala meals and fresh mountain trout.','A family restaurant with a long menu of Kerala curries, appam and grilled trout. Vegetarian options are strong and the spice level can be adjusted.','/images/food.jpg',10.0900,77.0580,'Munnar Town',900,4.2,640,'11:30 AM - 10:00 PM','11:30','22:00','Trout fry · Appam and stew · Avial · Palada payasam'),
('alleppey-toddy-shop',8,'Kuttanad Toddy Shop','Kerala, Seafood','Backwater fish curry with fresh toddy.','A local toddy shop serving karimeen and prawn curry with tapioca. Simple benches, fast service, and food that is best shared.','/images/food.jpg',9.5100,76.3450,'Kuttanad Road, Alleppey',700,4.4,430,'11:00 AM - 9:00 PM','11:00','21:00','Karimeen pollichathu · Prawn curry · Tapioca · Toddy'),
('marari-catch',8,'The Catch Marari','Seafood','Whatever the boats brought in, cooked simply.','A beachside kitchen with a daily board of the morning catch. Grilled, fried or in a coconut curry, with rice and a salad from the garden.','/images/food.jpg',9.6180,76.2840,'Mararikulam, Alleppey',1100,4.5,360,'12:00 PM - 10:00 PM','12:00','22:00','Grilled snapper · Coconut fish curry · Lemon rice · Tender coconut'),
('goa-fish-thali',9,'Fisherman''s Thali','Goan, Seafood','A Goan fish thali on a banana leaf.','A no-frills kitchen near the Panaji market serving fish thalis with rice, sol kadhi and a changing fry. Lunch service only.','/images/food.jpg',15.4970,73.8300,'Panaji Market, Goa',500,4.4,1180,'11:30 AM - 3:30 PM','11:30','15:30','Fish thali · Prawn balchao · Sol kadhi · Bebinca'),
('fontainhas-table',9,'Fontainhas Table','Portuguese, Goan','Portuguese-Goan cooking in a blue villa courtyard.','Six tables in a restored villa, with a menu of xacuti, sorpotel and grilled fish. Book at least a day ahead for dinner.','/images/food.jpg',15.4992,73.8280,'Fontainhas, Panaji',2200,4.6,520,'12:30 PM - 3:00 PM, 7:30 PM - 10:30 PM','12:30','22:30','Pork sorpotel · Chicken xacuti · Grilled prawns · Bebinca'),
('jaipur-handi',10,'Handi on the Roof','Rajasthani','Laal maas and dal baati with a rooftop view.','A walled-city rooftop restaurant with a long Rajasthani menu and a clear view of the Nahargarh ridge. The laal maas is the dish to order.','/images/food.jpg',26.9230,75.8250,'Badi Chaupar, Jaipur',1400,4.4,1560,'12:00 PM - 11:00 PM','12:00','23:00','Laal maas · Dal baati churma · Gatte ki sabzi · Ghewar'),
('pink-city-cafe',10,'Pink City Cafe','Cafe, Continental','Breakfast on a Hawa Mahal rooftop.','The best place to photograph Hawa Mahal over breakfast. Arrive before 8 AM for a window table and the soft morning light.','/images/food.jpg',26.9245,75.8270,'Hawa Mahal Road, Jaipur',700,4.2,1980,'7:00 AM - 6:00 PM','07:00','18:00','Masala chai · Eggs Benedict · Stuffed paratha · Cold coffee'),
('udaipur-lake-kitchen',11,'Lake Kitchen','Rajasthani, Indian','Dinner on a terrace above the lake.','A slow dinner restaurant with lake-facing tables and a Rajasthani menu with lighter, modern touches. Reserve for the 7:30 PM seating.','/images/food.jpg',24.5760,73.6815,'Ambrai Ghat, Udaipur',1900,4.5,760,'12:30 PM - 10:30 PM','12:30','22:30','Safed maas · Ker sangri · Dal baati · Rabri'),
('jaisalmer-fort-cafe',12,'Desert Fort Cafe','Cafe, Rajasthani','Cold coffee and kachori on the fort ramparts.','A tiny cafe inside the fort with a rooftop view over the desert. Simple food, cold drinks and a breeze that makes the climb worthwhile.','/images/food.jpg',26.9130,70.9130,'Jaisalmer Fort',500,4.2,520,'8:00 AM - 9:00 PM','08:00','21:00','Pyaaz kachori · Cold coffee · Ker sangri · Gulab jamun'),
('banaras-ghat-kitchen',13,'Ghat Kitchen','Banarasi, Vegetarian','Kachori, chaat and malaiyo in the old lanes.','A small counter in the lanes near Dashashwamedh serving breakfast kachori and evening chaat. Sit on the steps with the rest of the city.','/images/food.jpg',25.3070,83.0115,'Dashashwamedh, Varanasi',300,4.4,960,'7:00 AM - 10:00 PM','07:00','22:00','Kachori sabzi · Tamatar chaat · Malaiyo · Banarasi paan'),
('rishikesh-river-cafe',14,'River Cafe','Cafe, Continental','Breakfast on a deck above the Ganga.','A relaxed cafe with a long breakfast menu and a deck facing the river. Good for a slow morning after a rafting day.','/images/food.jpg',30.1250,78.3280,'Laxman Jhula, Rishikesh',800,4.3,1420,'8:00 AM - 9:00 PM','08:00','21:00','Bircher muesli · Shakshuka · Banana pancake · Cold brew'),
('leh-tibetan-kitchen',15,'Tibetan Kitchen Leh','Tibetan, Ladakhi','Thukpa and momos in a warm low-ceilinged room.','A long-running family restaurant near the main bazaar, with thukpa, momos and butter tea. Portions are generous and the room stays warm.','/images/food.jpg',34.1640,77.5780,'Main Bazaar, Leh',700,4.5,880,'9:00 AM - 10:00 PM','09:00','22:00','Thukpa · Steam momos · Butter tea · Skyu'),
('manali-orchard-cafe',16,'Orchard Cafe','Cafe, Himachali','Apple cake and siddu in a wooden cottage.','A slow cafe in Old Manali with a garden, a long brunch menu and local siddu on winter mornings.','/images/food.jpg',32.2510,77.1720,'Old Manali',800,4.3,640,'8:30 AM - 10:00 PM','08:30','22:00','Siddu · Apple cake · Trout · Butter tea'),
('darjeeling-glenarys',17,'Glenary''s','Cafe, Continental','Bakes, breakfast and a view of the range.','A Darjeeling institution on the mall road, with a bakery counter and a dining room facing the mountains. Book a window table.','/images/food.jpg',27.0430,88.2650,'Nehru Road, Darjeeling',900,4.4,1820,'7:30 AM - 9:30 PM','07:30','21:30','Cheese toast · Chicken sandwich · Darjeeling first flush · Rum ball'),
('pondy-bakery',18,'Rue de la Boulangerie','French, Cafe','Croissants and filter coffee in White Town.','A small French bakery with a courtyard, serving croissants, quiche and proper coffee. The morning queue moves quickly.','/images/food.jpg',11.9320,79.8330,'Rue Suffren, Pondicherry',700,4.5,1180,'7:30 AM - 7:00 PM','07:30','19:00','Croissant · Quiche Lorraine · Filter coffee · Chocolate eclair'),
('mahabalipuram-seafood',19,'Sea Shore Kitchen','Seafood, Tamil','Grilled fish a few steps from the temple.','A family restaurant with a terrace, serving grilled fish, prawn masala and Tamil meals. Good for a late lunch after the monuments.','/images/food.jpg',12.6200,80.1985,'Shore Temple Road, Mahabalipuram',800,4.2,540,'11:00 AM - 10:00 PM','11:00','22:00','Grilled pomfret · Prawn masala · Fish curry rice · Payasam'),
('shillong-jadoh',20,'Jadoh Stall','Khasi','Rice, pork and black sesame in a market kitchen.','A busy market stall serving jadoh with pork and a chilli chutney. Cheap, fast and one of the best things to eat in the northeast.','/images/food.jpg',25.5760,91.8910,'Iewduh Market, Shillong',400,4.5,660,'9:00 AM - 6:00 PM','09:00','18:00','Jadoh · Pork fry · Dohkhlieh · Black sesame chutney'),
('havelock-beach-cafe',21,'Lagoon Beach Cafe','Seafood, Continental','Fresh fish and cold drinks behind the dunes.','A relaxed beach cafe with a daily catch board, wood-fired pizza and a sunset deck. Breakfast runs from 7 AM for early divers.','/images/food.jpg',11.9870,92.9470,'Radhanagar, Havelock',1000,4.4,480,'7:00 AM - 10:00 PM','07:00','22:00','Grilled snapper · Wood-fired pizza · Coconut water · Banana pancake');
